Q: Layout and visual animations out of sync A: <h3>1. The Core Issue: Grid Flow vs. Transforms</h3>
<p>In a CSS Grid, every child takes up a row. If you have 12 rows and you use <code>translateY(-900%)</code> on the 10th row, it moves to the top visually, but the grid still thinks there are 12 rows of space being occupied.</p>
<p>To solve this without breaking <code>subgrid</code>, you need to:</p>
<ul>
<li><p>Keep the container <code>overflow: hidden</code>.</p>
</li>
<li><p><strong>Absolute Position the rows</strong> during the animation so they don't push the grid height out, OR (simpler) <strong>adjust the grid-row assignments</strong>.</p>
</li>
</ul>
<h3>2. The Optimized Solution</h3>
<p>Instead of complex <code>translateY</code> math, you can use <code>grid-row</code> and <code>opacity</code>. By assigning all &quot;collapsed&quot; rows to the same grid-row index, they will physically overlap at the top of the table, allowing the container height to transition smoothly.</p>
<pre><code>.table {
  display: grid;
  grid-template-columns: auto max-content;
  overflow: hidden;
  /* Use grid-template-rows to control row height strictly */
  grid-template-rows: 40px repeat(var(--total-items), 50px);
  height: calc(var(--number-of-rows) * 50px + 40px);
  transition: height 0.5s ease;
}

.table-row {
  display: grid;
  grid-template-columns: subgrid;
  grid-column: span 2;
  height: 50px;
  /* Smoothly fade out rows that are being &quot;hidden&quot; */
  transition: transform 0.5s ease, opacity 0.3s ease;
}

/* When collapsed, move non-selected rows to an invisible state */
.table-row.hidden {
  opacity: 0;
  pointer-events: none;
}
</code></pre>
<p>Recommended JavaScript Logic</p>
<p>Instead of calculating multipliers, simply toggle a class. Let the CSS handle the &quot;stacking.&quot;</p>
<pre><code>function updateTransforms() {
  const table = document.getElementById('table');
  const selectedIndex = state.items.findIndex(item =&gt; item.selected);

  // Logic: Show selected row + 2 rows below it (or above if at the end)
  let visibleIndices = [selectedIndex, selectedIndex + 1, selectedIndex + 2];

  // Adjust if we are at the end of the list
  if (selectedIndex &gt;= state.items.length - 2) {
    visibleIndices = [state.items.length - 3, state.items.length - 2, state.items.length - 1];
  }

  state.items.forEach((item, index) =&gt; {
    if (isOpen) {
      item.element.style.transform = `translateY(0)`;
      item.element.style.opacity = &quot;1&quot;;
    } else {
      if (visibleIndices.includes(index)) {
        // Move the visible rows to the top 3 slots
        const targetPos = visibleIndices.indexOf(index);
        const moveDistance = (index - targetPos) * 50; // 50px is row height
        item.element.style.transform = `translateY(-${moveDistance}px)`;
        item.element.style.opacity = &quot;1&quot;;
      } else {
        item.element.style.opacity = &quot;0&quot;;
      }
    }
  });

  const totalRows = isOpen ? state.items.length : 3;
  table.style.setProperty('--number-of-rows', totalRows);
}
</code></pre>
<p>In action:</p>
<p><div class="snippet" data-lang="js" data-hide="true" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code snippet-currently-hidden">
<pre class="snippet-code-js lang-js prettyprint-override"><code>let isOpen = false;
let state = {
  items: [],
  visibleRows: 3,
  isMultiSelect: false,
};

// Initialize state
function initializeState() {
  const rows = document.querySelectorAll('.table-row');
  state.items = Array.from(rows).map((row, index) =&gt; ({
    id: index,
    selected: row.querySelector('input').checked,
    transformMultiplier: 0,
    element: row,
  }));
  calculateTransforms();
}

// Port of the calculateTransforms function from React component
function calculateTransforms() {
  const selectedRows = state.items.reduce(
    (count, item) =&gt; count + (item.selected ? 1 : 0),
    0,
  );
  let gracePortion = Math.max(0, 3 - selectedRows);
  let distance = 0;
  const distances = [];

  const firstPass = state.items.map((item, index) =&gt; {
    let transformMultiplier = null;

    if (item.selected) {
      transformMultiplier = distance;
      distances.push(distance);
    } else if (gracePortion &gt; 0) {
      transformMultiplier = distance;
      distances.push(distance);
      gracePortion--;
    } else if (state.items.length === index + 1) {
      distance++;
      transformMultiplier = distance;
      distances.push(distance);
    } else {
      distance++;
    }

    return {
      ...item,
      transformMultiplier: transformMultiplier
    };
  });

  let distancePosition = 0;
  const items = firstPass.map((item) =&gt; {
    let transformMultiplier = item.transformMultiplier;
    if (transformMultiplier === null) {
      transformMultiplier = distances[distancePosition];
    } else {
      distancePosition++;
    }

    return {
      ...item,
      transformMultiplier: transformMultiplier
    };
  });

  state.items = items;
  state.visibleRows = Math.max(3, selectedRows);

  updateTransforms();
}

function updateTransforms() {
  const table = document.getElementById('table');
  const totalRows = isOpen ? state.items.length : state.visibleRows;

  // Update CSS custom property for table height
  table.style.setProperty('--number-of-rows', totalRows);

  state.items.forEach((item, index) =&gt; {
    const translateY = isOpen ? 0 : -item.transformMultiplier * 100;
    item.element.style.transform = `translateY(${translateY}%)`;
    item.element.style.zIndex = state.items.length - index;
  });
}

function toggleRows() {
  isOpen = !isOpen;
  const button = document.querySelector('.footer-button');
  const chevron = document.getElementById('chevron');

  button.innerHTML = isOpen ?
    'Show less &lt;span class="chevron open" id="chevron"&gt;&lt;/span&gt;' :
    'Show more &lt;span class="chevron" id="chevron"&gt;&lt;/span&gt;';

  calculateTransforms();
}

// Handle radio button changes
function handleSelectionChange() {
  const rows = document.querySelectorAll('.table-row');
  rows.forEach((row, index) =&gt; {
    const input = row.querySelector('input');
    state.items[index].selected = input.checked;
  });
  calculateTransforms();
}

// Initialize on page load
document.addEventListener('DOMContentLoaded', function() {
  initializeState();

  // Add event listeners to radio buttons
  const inputs = document.querySelectorAll('input[type="radio"]');
  inputs.forEach((input) =&gt; {
    input.addEventListener('change', handleSelectionChange);
  });
});

// new JS:

// Source - https://stackoverflow.com/a/79859098
// Posted by thushara sandakelum
// Retrieved 2026-01-03, License - CC BY-SA 4.0

function updateTransforms() {
  const table = document.getElementById('table');
  const selectedIndex = state.items.findIndex(item =&gt; item.selected);

  // Logic: Show selected row + 2 rows below it (or above if at the end)
  let visibleIndices = [selectedIndex, selectedIndex + 1, selectedIndex + 2];

  // Adjust if we are at the end of the list
  if (selectedIndex &gt;= state.items.length - 2) {
    visibleIndices = [state.items.length - 3, state.items.length - 2, state.items.length - 1];
  }

  state.items.forEach((item, index) =&gt; {
    if (isOpen) {
      item.element.style.transform = `translateY(0)`;
      item.element.style.opacity = "1";
    } else {
      if (visibleIndices.includes(index)) {
        // Move the visible rows to the top 3 slots
        const targetPos = visibleIndices.indexOf(index);
        const moveDistance = (index - targetPos) * 50; // 50px is row height
        item.element.style.transform = `translateY(-${moveDistance}px)`;
        item.element.style.opacity = "1";
      } else {
        item.element.style.opacity = "0";
      }
    }
  });

  const totalRows = isOpen ? state.items.length : 3;
  table.style.setProperty('--number-of-rows', totalRows);
}</code></pre>
